/* Galician Names Database — name-meaning lookup demo (jahdb-demo-1.0)
 * RUN ON PC: save as demo.js, then run:  node demo.js [name]
 * RUN IN BROWSER: paste into the console and press Enter. */
var TABLE = {"Xose": "God increases — Hebrew Yosef", "Maria": "The most beloved Galician feminine name.", "Anton": "priceless — Latin Antonius", "Uxia": "well-born — Greek Eugenia", "Breogan": "The mythical Celtic king of Galicia.", "Iria": "A feminine name from the ancient Galician town.", "Fernandez": "A classic -ez patronymic.", "Lopez": "A classic -ez patronymic.", "Rodriguez": "A classic -ez patronymic.", "Gonzalez": "A classic -ez patronymic."};
function lookup(q){
  q=String(q||'').toLowerCase().trim();
  var keys=Object.keys(TABLE);
  for(var i=0;i<keys.length;i++){ if(keys[i].toLowerCase()===q) return keys[i]+' — '+TABLE[keys[i]]; }
  var hits=keys.filter(function(k){return k.toLowerCase().indexOf(q)>=0;});
  if(!hits.length) return 'No match for "'+q+'". Try: '+keys.slice(0,5).join(', ');
  return hits.map(function(k){return k+' — '+TABLE[k];}).join('\n');
}
var q=(typeof process!=='undefined'&&process.argv[2])||'Xose';
console.log(lookup(q));

